CREATE OR REPLACE PROCEDURE big_flow IS
BEGIN

  -- pedidos → inventario
  INSERT INTO TBL_INVENTARIO
  SELECT * FROM TBL_PEDIDOS;

  -- inventario → reservas
  INSERT INTO TBL_RESERVAS
  SELECT * FROM TBL_INVENTARIO;

  -- reservas → envios
  INSERT INTO TBL_ENVIOS
  SELECT * FROM TBL_RESERVAS;

  -- pedidos → clientes
  INSERT INTO TBL_CLIENTES
  SELECT * FROM TBL_PEDIDOS;

  -- clientes → marketing
  INSERT INTO TBL_MARKETING
  SELECT * FROM TBL_CLIENTES;

  -- marketing → campañas
  INSERT INTO TBL_CAMPANAS
  SELECT * FROM TBL_MARKETING;

  -- envios → tracking
  INSERT INTO TBL_TRACKING
  SELECT * FROM TBL_ENVIOS;

  -- tracking → analytics
  INSERT INTO TBL_ANALYTICS
  SELECT * FROM TBL_TRACKING;

  -- analytics → reportes
  INSERT INTO TBL_REPORTES
  SELECT * FROM TBL_ANALYTICS;

  -- inventario → facturación
  INSERT INTO TBL_FACTURAS
  SELECT * FROM TBL_INVENTARIO;

  -- facturación → contabilidad
  INSERT INTO TBL_CONTABILIDAD
  SELECT * FROM TBL_FACTURAS;

END;
